insert into TB_LGCL_REL_ATRB(LGCL_REL_ATRB_SN, LGCL_REL_SN, ORGNL_ATRB_SN, TRGT_ATRB_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_REL_ATRB, r.LGCL_REL_SN, pm.LGCL_ATRB_SN, cm.LGCL_ATRB_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_LGCL_MDL' join TB_COL cc on cc.TBL_SN = ct.TBL_SN and cc.COL_NM = 'LGCL_MDL_SN' join TB_COL pc on pc.TBL_SN = pt.TBL_SN and pc.COL_NM = 'LGCL_MDL_SN' join TB_ATRB_COL_MPNG cm on cm.COL_SN = cc.COL_SN join TB_ATRB_COL_MPNG pm on pm.COL_SN = pc.COL_SN join TB_LGCL_REL r on r.PRJ_SN = 0 and r.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'LGCL_MDL_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조' where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_LGCL_SBJ_AREA_LYT' and not exists (select 1 from TB_LGCL_REL_ATRB x where x.LGCL_REL_SN = r.LGCL_REL_SN);
