update TB_TBL set TASK_EXPLN = '논리 모델의 엔터티를 업무 영역별로 나누어 보는 분류. 상위 영역 아래에 최대 3단계까지 두며, 같은 상위 아래에서는 이름이 겹치지 않는다 (대소문자 무시). 엔터티의 정의·승인 상태와는 관계없다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '주제 영역을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and COL_NM = 'LGCL_SBJ_AREA_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 행이 속한 프로젝트. 조회와 변경은 로그인할 때 고른 프로젝트 안으로 제한되며, 프로젝트를 지우면 함께 지운다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '주제 영역이 속한 논리 모델. 다른 모델의 엔터티·영역과 섞이지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and COL_NM = 'LGCL_MDL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '상위(부모) 주제 영역. 비어 있으면 최상위(1단계) 영역이다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and COL_NM = 'UP_SBJ_AREA_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '주제 영역 이름. 같은 상위 영역 아래에서 대소문자 구분 없이 하나뿐이다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and COL_NM = 'SBJ_AREA_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '주제 영역이 다루는 업무 범위 설명.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA' and COL_NM = 'SBJ_AREA_EXPLN' and TASK_EXPLN is null;
