update TB_TBL set TASK_EXPLN = '엔터티가 어느 주제 영역에 속하는지 기록한다. 엔터티 하나는 영역 하나에만 속하고, 행이 없으면 미분류다. 분류를 바꿔도 엔터티 자체는 수정되지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA_ENTT' and TASK_EXPLN is null;
