update TB_TBL set TASK_EXPLN = '논리 ERD 를 주제 영역 범위로 볼 때의 개인 화면 배치. 사용자·주제 영역별로 엔터티 위치와 화면 위치·배율을 저장하며, 모델 전체 배치와 서로 영향을 주지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBJ_AREA_LYT' and TASK_EXPLN is null;
